// Thin client wrapper around the Catalyst Advanced I/O function that
// proxies to Gemini. No API key lives here or anywhere in the frontend —
// the function endpoint is the only thing this file knows about.
//
// Mirrors the request/response shape of submitApplicationToAWS in
// awsService.js: async, throws on failure, minimal.

const ASSISTANT_FUNCTION_URL =
  process.env.REACT_APP_CATALYST_ASSISTANT_FUNCTION_URL;

/**
 * Sends the user's spoken/typed utterance plus current application
 * context to the backend, gets back a structured intent + natural
 * language reply. Does NOT decide what happens next in the application
 * flow — useApplicationSession still owns that. This just interprets
 * free-form speech into something the existing flow can act on.
 *
 * @param {string} transcript - what the user said
 * @param {object} context - { currentStepId, stepType, options, answers, stage }
 * @returns {Promise<{ reply: string, intent: string, value?: any }>}
 */
export async function interpretUserSpeech(transcript, context) {
  if (!ASSISTANT_FUNCTION_URL) {
    throw new Error('Assistant function URL is not configured.');
  }

  const response = await fetch(ASSISTANT_FUNCTION_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ transcript, context }),
  });

  if (!response.ok) {
    throw new Error(`Assistant function error: ${response.status}`);
  }

  return response.json();
}

export default { interpretUserSpeech };
